insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place)
values
(E'https://matcha-jp.com/cn/4616', E'zh-Hans', 17, E'石川县“松波酒造”的日本酒，150年不变的传统味道', E'松波酒造开业于1868年石川县能登半岛，至今仍坚持以传统制法酿出香醇的日本酒，为符合现代人的口味不断地更改制程，创造出各种丰富变化的日本酒。有到能登半岛旅游时一定要去看看。\n\n“大江山纯米酒”口感清爽的，细品又回味无穷，冰镇后饮用，不仅适合于日本料理，还和香菇奶油意大利面特别搭。\n\n这样的大江山纯米酒就是在“松波酒造”制造的日本酒。这间酒造有座很多高品质且独家的日本酒，也有提供很多品牌。\n\n位于石川县的能登半岛是个知名的历史街道，有许多观光景点。有关日本酒的话，可以说是“杜氏”育成的地方。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/21-29295.webp"]'::jsonb, E'2017-11-28'::timestamptz, E'能登半岛'),
(E'https://matcha-jp.com/cn/4978', E'zh-Hans', 18, E'【福井】漫步名胜养浩馆庭园，享受江户藩主的闲情与风雅', E'多次名列日本最优庭园前十名的福井养浩馆庭园，虽说是江户名园，其实这样的水岸美景与园艺、池畔亲水的生活美学超越了时代，即便是现今也是让人觉得很有艺术性的日式建筑。\n\n走进养浩馆庭园，映入眼帘的是满满的绿意，与匠人细心琢磨的数寄屋建筑，园中池占据了庭园很大的范围，眼前的景致随着移动变化，走完一圈就像看完一本画册似的。\n\n进到屋内，在缘侧坐下，眺望环池美景，视线时而被池中悠游的锦鲤所吸引，时而被绚丽的光影所占据，享受宁静和煦的氛围，任时间缓缓流逝。这样的空间与片刻，让人觉得安心、放松，消抹了旅途的紧张与疲累，洗涤了旅人的心灵。\n\n养浩馆庭园，江户时代的代表名园，福井藩主松平家的别邸，古时称作“御泉水屋敷”。成立时期不详，一般认为是第三代藩主(1623-1645)将福井城下的饮用水路“芝原上水”引入建造园中池，奠定了庭园的雏形。而规模与形式的完成则推敲是在第七代藩主(1686-1703)之时。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35009.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35069.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35071.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35073.webp"]'::jsonb, E'2017-09-11'::timestamptz, E'福井市'),
(E'https://matcha-jp.com/cn/9571', E'zh-Hans', 18, E'从金泽可当日往返！福井县必游观光景点＆美食13选', E'位于北陆地方的福井县，拥有众多看点，如绝景东寻坊(Toujinbou)和冬季美味越前(Echizen)蟹等！ 因为从热门城市金泽可当日往返，推荐组合旅行。本文为初次造访福井县的人们介绍必游观光景点和美食等模范旅游路线。\n\n位于日本北陆地方的福井县，面朝大海，由南向北狭长地延伸，北部和南部的方言和文化各异。北部与金泽所在的石川县接壤，是一处拥有深厚北陆地方特有文化根源的地方。此外，南部临近京都，自古以来便深受关西地区文化的影响。\n\n还有，这里四季分明，除了应季美景之外，夏天可品尝海胆和牡蛎(Kaki)、冬天可品尝螃蟹和河豚等美味，物产丰富。\n\n福井县至今出土了大量恐龙化石，站前广场也以此为宣传点，设置了一个实物大小的可动恐龙纪念碑和脚印(复制)，并设有以恐龙为主题的错觉艺术作品。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100842.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100846.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100847.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/25-100242.webp"]'::jsonb, E'2020-05-28'::timestamptz, E'福井市'),
(E'https://matcha-jp.com/cn/5920', E'zh-Hans', 18, E'【北陆】春烂漫！福井县在地人推荐赏樱景点8选', E'MATCHA福井当地小编，为大家整理了北陆福井县的赏樱景点8选，足羽山公园,丸冈城,西山公园等地，快来看看福井有什么浪漫樱花景致吧。\n\n春游日本，赏樱当然是不可错过的重头戏！MATCHA福井在地小编，整理了福井县的赏樱景点8选。北陆地区的福井因纬度较高，樱花绽放比起关东、四国等地区较晚一、两个礼拜，动身前往赏樱前，先跟着小编来看看福井有什么浪漫樱花景致吧！ 2019年预测福井开花日期为3月29日\n\n说到福井的樱花景点，在地人绝对首先推荐入选“樱花百选”的“足羽川河畔樱花并木”。足羽川是流经福井市的一条大河，靠近市中心段的河堤上有约600棵的染井吉野樱并排而种，绵延2.2公里之长。福井市的樱花祭就在这一带的河畔边举行，所以人潮相对会比较多一些，热闹但不至于拥挤，还是能优闲地赏樱。\n\n樱花并木分列河堤两旁，漫步期间，宛如穿过粉红色隧道。有时候，春风一吹，花瓣飘落翩翩飞舞，浪漫至极。2019的福井樱花祭从3月30日到4月14日。届时足羽河畔的餐厅、店家都会推出期间限定的赏樱特别菜色或优惠。京福巴士于期间的周六、周日及假日特别行驶市内赏樱周游巴士，乘车费一律200日元，非常划算。详细情报请参考官网。 查看资讯 第34届福井市樱花祭 第34届福井市樱花祭 View Map \' 地址 足羽河原堤防・足羽山・福井城址など Wi-Fi 无 信用卡及其使用种类 无 最近车站 JR福井站 交通方式 JR福井站步行15分钟 费用 免费 电话号码 福井市おもてなし観光推進課 0776-20-5346 官网 第34届福井市樱花祭', E'["https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51151.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51152.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51153.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51154.webp"]'::jsonb, E'2018-04-05'::timestamptz, E'福井市'),
(E'https://matcha-jp.com/cn/7701', E'zh-Hans', 19, E'【富士急乐园】《火影忍者》迷必去！全新园区“NARUTO×BORUTO 富士木叶忍者村”重点攻略', E'2019年7月26日富士急乐园推出全新主题专区“NARUTO×BORUTO 富士木叶忍者村”，让你体验成为火影忍者的酷炫、尝试各种忍术、饱尝鸣人爱吃的拉面，以及入住“忍之间”火影套房享受被鸣人与佐助拥入怀中的温暖。抹茶小编将介绍新园区的重点设施，火影迷千万不可错过！\n\n而2019年夏天，富士急乐园更与超人气漫画作品《火影忍者》携手合作推出“NARUTO×BORUTO 富士木叶忍者村”主题园区，让无法体验刺激系游乐设施的人，也能够轻松享受成为火影忍者的快感，也势必让富士急乐园成为世界各国动漫迷必访的圣地！\n\n从2018年7月14日开始，富士急乐园开始“入园免费”的服务，而顾客只需针对想要搭乘的设施来付费即可。若是一日当中想要体验多项游乐设施的人，建议可以购买不限搭乘次数的一日券，若只是想要玩几项的人，则推荐购买想玩的游乐设施的票券即可。另外，必须要特别注意的是“NARUTO×BORUTO 富士木叶忍者村”的部分设施，不包含在一日券使用范围之内，在体验之前请务必事先确认。 各项设施的详细体验费用，将于下文中进行说明。\n\n“NARUTO×BORUTO 富士木叶忍者村”提供多项忍者体验以及独创的美食料理，以下为相关设施的费用与使用限制一览表。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/07/23-82064.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/23-82125.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/23-82065.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/23-82067.webp"]'::jsonb, E'2019-08-06'::timestamptz, null),
(E'https://matcha-jp.com/cn/4995', E'zh-Hans', 19, E'『小编的第一次』一辈子一定要爬一次！富士山登顶攻略', E'日本的第一高峰富士山，每年限定7、8月开放登山，不仅日本人热爱攀登，外国旅客也趋之若鹜。究竟登富士山有什么魅力？MATCHA带你从行程准备到五合目四条登山路线说谜名到攻顶下山一起走一遭！\n\n大家对富士山的印象，势必是有着白头（冠雪）的典型模样吧？然而，富士山的登山季节，则是必须等山顶积雪退去的夏季才能攀爬，每年的开山季节约落在7、8月，以去年（登山在2017年）和今年（2018年）来说是落在7月1日～9月10日，周末人潮众多，尤其8月中“山之日”假期，可说是整座山头都是登山客“排队”爬山。\n\n吉田线是所有路线中，最多登山客选择的路线，登山口（富士Subaruline付费道路五合目）有不少商店，回程可购买伴手礼或是上山前下山后稍事休息、用餐。\n\n距离山顶标高约1,400公尺，往复约14公里，上山约需要6个小时，下山则约3个小时30分钟。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/09/04-35294.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/04-35296.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/04-35297.webp"]'::jsonb, E'2018-09-03'::timestamptz, null),
(E'https://matcha-jp.com/cn/6134', E'zh-Hans', 19, E'富士山下！到百年茅葺屋享传统端炉烧：山麓园 Sanrokuen', E'位在富士山山梨县的山麓园 Sanrokuen餐厅，用餐方式有点特别! 可以在店内围在炉火前吃饭或取暖聊天，仿佛时光回到以前日本那样的围炉方式。一家人坐在炉火前吃饭或取暖聊天，享受和乐融融的氛围。\n\n日本之旅尝了不少在地传统料理，让人回味无穷。现要与大家分享的是一家位于河口湖附近的百年茅草屋餐厅 – 山麓园 Sanrokuen，提供传统炉端烧料理，食材美味丰富，享用美食当下还能体验烧烤乐趣。\n\n除了串烧食材外，另提供山梨县传统料理馎饦面，为手工粗面条与南瓜等蔬菜熬煮的健康锅品，让人饱足又满意的一餐。\n\n我们在离开了 いやしの里根场 后，来到山麓园享用晚餐，那时大约下午五点天色还亮着，欣赏庭院绿意清幽的环境觉得舒适，也许有人因为它的外观觉得餐点价格高而打退堂鼓，但请放心～餐点也有平价路线，CP 值很高喔！', E'["https://resources.matcha-jp.com/resize/720x2000/2018/05/24-54789.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/24-54776.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/24-54777.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/24-54778.webp"]'::jsonb, E'2018-07-30'::timestamptz, E'河口湖'),
(E'https://matcha-jp.com/cn/4463', E'zh-Hans', 20, E'【长野】小心，机关重重！ 长野户隐“忍者からくり屋敷”', E'因为一套动画《火影忍者》，便迷上了“忍者”这种主题，走访长野县时，当然要去会一会人称“忍者的故乡”的户隐忍者村。这里的忍者属于户隐流派，而所有关于户隐流忍者的事，都暗藏在户隐流忍法资料馆与忍者からくり屋敷中！\n\n因为《火影忍者》便迷上了“忍者”这种主题，总觉得他带有一点神秘，像是独特于世的存在。走访长野县时，当然要去会一会这个人称“忍者的故里”的户隐。这里的忍者属于户隐流，而所有关于户隐忍者的事，都藏深在户隐流忍法资料馆与忍者からくり屋敷中，今天就跟着MATCHA小编一起去勇闯机关屋！\n\n刚开始听见资料馆，一直以为是一座小型博物馆，没想的竟是一个类似忍者村落的场所，且分有不同的活动区域。入场费，成人都是每位600日圆，若是中小学生则是400日圆。\n\n因为参观的时间不多，所以即使知道有资料馆、民俗馆等较文化资料性的区域，也未能抽到时间到访。跟同行朋友的目标只有一个，就是要率先玩转忍者机关宅院！', E'["https://resources.matcha-jp.com/resize/720x2000/2017/05/22-26950.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/22-26951.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/22-26952.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/22-26953.webp"]'::jsonb, E'2017-06-10'::timestamptz, E'长野市'),
(E'https://matcha-jp.com/cn/7417', E'zh-Hans', 20, E'【旧轻井泽】面包才是你该品尝的轻井泽风味！人气面包旗舰店SAWAMURA', E'轻井泽有许多美食，其中不乏多家人气面包店，其中一家就是在东京与名古屋都有分店的【SAWAMURA】。本篇将介绍旧轻井泽的旗舰店，不仅交通方便，也靠近旧轻井泽银座商店街。逛街累了，不如来这里享用每日出炉的多种面包，在舒适的环境中体验轻井泽的悠闲浪漫吧！\n\n轻井泽是东京人的避暑胜地，也是游客的观光热门景点。从东京市区不到两小时就可以远离城嚣，放松泡温泉或吃美食。这一次Matcha小编要为大家介绍就在旧轻井泽的日本人气面包店— SAWAMURA（沢村）。\n\n这家轻井泽的人气面包店 SAWAMURA（沢村）就位在旧轻井泽银座附近，逛街逛累了、想远离拥挤人潮，都可以来这里找个位置休息一下，享用现烤出炉的美味面包。\n\nSAWAMURA占地广大且店内空间宽敞。整栋建筑简单分为3个区块，推开大门最先可以看到面包和咖啡吧台区，右手边则是附属的餐厅和酒吧。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/14-76817.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/14-76822.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/14-76821.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/14-76820.webp"]'::jsonb, E'2019-06-06'::timestamptz, null),
(E'https://matcha-jp.com/cn/4643', E'zh-Hans', 20, E'『长野』步入葛饰北斋作画之地：小布施町一日散策', E'大家来到长野时都去哪里观光呢？去滑雪？去轻井泽避暑？去看松本城跟上田城？其实长野市区有个名为“小布施町”的小镇，那里弥漫着一股故我的气息，一种自成一格的调调，并且也曾是浮世绘大师葛饰北斋曾经驻留之地，怀旧悠悠的味道油然而生。\n\n大家来到长野时都去哪里观光呢？去滑雪？去赏樱？去看城？其实长野市区周边有个名为“小布施町”的小镇，那里弥漫着一股故我的气息，一种自成一格的调调，并且也曾是浮世绘大师葛饰北斋曾经驻留之地，怀旧悠悠的味道油然而生。\n\n小布施町，因为土壤与气候的关系而盛产板栗，所以有“板粟之乡”的称呼。从长野车站出发，搭长野电铁约半个小时的车程，就能来到小布施站。或许因为还没沾染上繁华的观光气息，所以这里有着一股清幽的氛围，适合当作轻松的散步日程。\n\n虽然设有周游巴士，不过班次并不多，错过了一班车就要等很久所以建议大家要事先查询。而事实上，从小布施车站走去小镇之中，也只是十来分钟的时间，想要好好尽情感受在地氛围的话可以选择徒步过去。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29525.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29528.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29529.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29530.webp"]'::jsonb, E'2017-07-11'::timestamptz, E'松本城'),
(E'https://matcha-jp.com/cn/4885', E'zh-Hans', 21, E'数寄屋・末广之家〜在飞驒古川日本古宅度过的两日非日常体验〜', E'在古老街道中度过与平时截然不同的悠闲时光、这里是岐阜县的飞驒古川。「數寄屋・末廣之家」是可以充分感受飛驒古川魅力的包棟住宿。除了住宿的魅力外、也整理出古川的街道散步、电影『你的名字。』的朝圣之旅等等各种享受飞驒古川的玩乐方式。\n\n飞驒因为拥有深山的优质木材、自古以来木工产业兴盛。另外、历史上曾经以派遣木工工匠的方式取代向中央政府纳税、京都风的建筑様式也在这块土地生根。\n\n这次介绍的数寄屋・末广之家(以下简称：末广之家)也是能接触飞驒传统建筑文化的设施之一。这栋包栋的住宿设施，位于古老民家林立的街上、由飞驒里山OFFICE＆STAY(HIDA SATOYAMA OFFICE&STAY)经营。利用日本式的宅邸改装的住宿、最适合在周遭充满日本风味的城市与建筑物中度过悠闲时光。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/08/13-33469.webp"]'::jsonb, E'2017-10-10'::timestamptz, E'岐阜市'),
(E'https://matcha-jp.com/cn/4570', E'zh-Hans', 21, E'走到世界遗产“白川郷”，欣赏建筑合掌造，一窥“和田家”旧时风貌', E'位于岐阜县世界遗产“白川郷”的合掌造代表“和田家”。同时也是国家指定重要文化财的和田家、开放游客进入合掌造当中参观。这次将介绍和田家的内部样貌。\n\n以“合掌造”聚落闻名的世界遗产“白川乡”。每到冬天、白川郷周边容易产生大量积雪、为了让积雪易于滑落地面而兴建陡峭的茅草屋顶(※1)。这种屋顶形状很像合掌(※2)的样子、因此被称为“合掌造”。\n\n※1：茅草屋顶……以芒草等野草覆盖房屋的屋顶。 ※2：合掌……祈祷时双手合十的手掌模样。\n\n“和田家”建于江戸时代中期、是拥有300年以上悠久歴史的白川乡最大规模合掌造民家也是国家指定重要文化财。如同“和田家”这个名字、和田一家仍然居住在展示部分以外的空间。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/09-28462.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/09-28466.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/09-28468.webp"]'::jsonb, E'2017-10-13'::timestamptz, E'白川乡'),
(E'https://matcha-jp.com/cn/5244', E'zh-Hans', 21, E'【岐阜】走进《你的名字》来场老街巡礼，细细品味“飞驒古川”', E'通常大家来到岐阜“飞驒古川”，都是踩点《你的名字》电影场景，不过小编觉得，“飞驒古川”有很多细节值得细细品味，不如换上和服，来趟圣地巡礼兼老街巡礼吧！\n\n因为动画电影《你的名字》而一夕成名的岐阜县，成为许多人圣地之旅的第一目标，除去电影要素，飞驒古川也是处古色古香的老街，适合漫步走上一日。\n\n2016年日本动画电影《你的名字》爆红，剧中场景纷纷成为海内外观光客的朝圣地点，原本宁静的小镇“飞驒古川”因而人气高涨，除了踩点电影中的实际场景，MATCHA小编今天则推荐“老街漫步”，仔细享受老街中的独有气氛。\n\n来到和风老街，小编强力推荐必做的事就是：和服变身。想一想，在满是和式木造建筑的街道上，穿上日式传统服饰，日式x日式的标准组合，不管是拍照留念，或是心境上都会特别不一样呢。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/10/24-39468.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/24-39467.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/24-39466.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/24-39464.webp"]'::jsonb, E'2017-11-08'::timestamptz, E'岐阜市'),
(E'https://matcha-jp.com/cn/3938', E'zh-Hans', 22, E'热海旅游完全指南〜观光景点、温泉住宿、活动等【2023年版】', E'位于静冈县的热海是从东京可以当日往返旅游的温泉地。本篇文章汇总介绍了前往热海的方式、观光景点、温泉设施、酒店的费用和热海的庆典活动等热海的观光情报。\n\n热海是位于神奈川县旁的静冈县内的温泉地。这裏是临海的温泉地区，充满度假气息，吸引了来自日本全国各地的游客来访。同时，从东京搭乘新干线前往此地只需50分钟，搭乘普通列车则只要2个小时就能到达。因此这裏也是关东近郊人们的周末旅行首选观光景区之一。\n\n对于海外游客，推荐大家在逛完东京后，花上2天1夜来这裏看看。这裏有着与东京都中心完全不同的氛围，可以享受在全日本温泉量数一数二的优质温泉。\n\n从东京前往热海可以搭乘东海道新干线「回声号（Kodama/こだま）」、特急列车「舞者号（Odoriko/踊り子）」、东海道线的普通列车或者巴士。其中新干线的时间最短，为50分钟，需要4000日圆。而费用上则以高速巴士最便宜，为1,500～2,000日圆，所需时间则为2小时30分～3小时。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17537.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17533.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17500.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17501.webp"]'::jsonb, E'2017-06-05'::timestamptz, E'热海市'),
(E'https://matcha-jp.com/cn/7986', E'zh-Hans', 22, E'【静冈】伊豆到底是什么地方？伊豆半岛、景点、温泉住宿介绍', E'每年最早开的樱花河津樱就在静冈伊豆，这个关东地区温泉胜地“伊”」到底在哪里？为什么搜寻伊豆时，总会跑出热海、箱根？而这里必访的景点与温泉旅馆有哪些？就让这篇文章为你解答吧！\n\n关东地区温泉胜地【伊豆】，你知道它跟热海的关系吗？是伊豆就是热海？还是根本就是箱根呢？这篇文章带你了解伊豆真面目，外加玩耍景点推荐喔！\n\n说到东京近郊温泉景点，就是伊豆、热海与箱根的排列组合，看起来好像他们很近？还是根本就在同一个地方？\n\n箱根在神奈川县的南部，再往南则是另一个温泉地“汤河原”，汤河原刚好位于神奈川县与静冈县交界，紧邻汤河原的就是静冈县热海。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/27-86844.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/27-86824.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/27-86840.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/27-86841.webp"]'::jsonb, E'2019-10-25'::timestamptz, E'伊豆半岛'),
(E'https://matcha-jp.com/cn/7750', E'zh-Hans', 22, E'【静冈】樱桃小丸子家的超级市场！ ？来“清水河岸鱼市场”大啖超值豪华海鲜', E'清水除了三保松原、樱桃小丸子之外，还有丰富海鲜，今天将要介绍这间位于车站旁的“清水河岸鱼市场”，市场里网罗十几家海鲜餐厅，绝对是来静冈旅游时大啖海鲜美食的好所在！\n\n静冈县的“清水市”，是漫画《樱桃小丸子》的故乡，相信大家都不陌生。位于骏河湾的清水市依山傍水，即能远眺富士山，市内的清水港还有各种海鲜品尝。本持 “为了更方便大家购买品尝这些新鲜的海鲜”这样想法，越来越多的业者聚集起来，组成了“清水鱼市场 河岸之市”。 市场分成两栋：鲔鱼馆 (まぐろ馆)、市场馆 (いちば馆)，周末总是聚集不少观光客或当地人前往购买、品尝海鲜。\n\n市场馆网罗20间店铺，贩售新鲜海产、蔬菜、干货，种类丰富，可说是清水港当地的“超级市场”。听着店家吆喝叫卖的声音此起彼落，购买欲望之火也会随之熊熊燃起。\n\n虽然主要用餐区域在隔壁的鲔鱼馆，但市场馆内也有贩售可以带着走的海鲜丼饭、海鲜类的熟食。不想排队的游客，也可以考虑直接购买这些丼饭熟食带着走。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/08/06-83180.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/06-83181.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/06-83182.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/06-83184.webp"]'::jsonb, E'2019-08-27'::timestamptz, E'富士山'),
(E'https://matcha-jp.com/cn/1669', E'zh-Hans', 23, E'【日本小百科】东海地方', E'对于来日本旅游的游客，我们将解释难懂的日语和日本特有的术语。这次是“东海地区”。介绍位于日本列岛和本州中部的东海地区的都道府县和旅游景点。\n\n东海地方位于本州的正中央，由面向太平洋的爱知县，静冈县，岐阜县构成。夏天属于降水量较多的区域，冬天则是晴天较多的气候，这边最大的都市为人口约229.8万人(2016年的时点)的名古屋市。\n\n世界最大规模的汽车厂商TOYOTA自动车的本社就位于东海地方，因此自动车产业担任了这个地区的经济主轴。经济规模仅次于关东和关西地方，为第三大经济地区。\n\n东海地方拥有独自的文化，不同于关东和关西。无论婚丧喜庆都非常独特，特别是有关结婚的文化很特别也很有名。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/05/25-127166.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/25-127163.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/25-127167.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/25-127168.webp"]'::jsonb, E'2016-03-27'::timestamptz, E'名古屋市'),
(E'https://matcha-jp.com/cn/4733', E'zh-Hans', 23, E'直击名古屋乐高乐园！必玩必吃全攻略！', E'位于名古屋的LEGOLAND® Japan乐高乐园，总面积虽然只有9.3公顷，不过麻雀虽“小”五脏具全，园内七大区各有特别，如果时间不够也挺难做决定，让小编帮大家整理5大重点攻略，去到就不用烦啦！\n\n位于名古屋的LEGOLAND® Japan，总面积虽然只有9.3公顷，不过麻雀虽“小”五脏具全，园内七大区各有特别，如果时间不够也挺难做决定，让小编帮大家整理5大重点攻略，去到就不用烦啦！\n\n作为主场代表的名古屋城高2.1米，震撼全场！同场还有另一代表OASIS 21，看完后有兴趣可以直接加入行程当中。\n\n平常去东京总是人很多，但看缩景就不用跟人挤啦！涩谷十字路口、东京站、台场高达、浅草寺让你任拍，可爱之处在于109变了601！', E'["https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32450.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32449.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32448.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32447.webp"]'::jsonb, E'2017-11-03'::timestamptz, E'名古屋市'),
(E'https://matcha-jp.com/cn/11795', E'zh-Hans', 23, E'在【AEON MALL永旺梦乐城 名古屋则武花园】品美食，赏星空，零距离体验艺术之美', E'2021年10月名古屋车站再次受到人们的瞩目。原因便在于车站附近新建的大型购物中心【AEON MALL永旺梦乐城 名古屋则武花园】。购物中心内除了多家首次进驻名古屋的人气店家之外，还有热门网美景点“茑屋书店”及星空体验设施“满天”。 强烈建议为【AEON MALL永旺梦乐城 名古屋则武花园】安排整日的行程，保证不管是情侣、家族或是一个人都能感受到充实的一天。就让小编带大家探索这间新景点吧！\n\n距离名古屋车站只要步行约12分钟，就可抵达与大楼林立不一样的地方AEON MALL永旺梦乐城 名古屋则武花园。这次的永旺梦乐城以“大自然共融”为概念，周边种植许多树木和草皮仿佛在树林中一样，室内也随处可见植物和设施融为一体，还设置许多休息区让在疫情下的我们也能这里放松心情去购物。\n\n馆内1～3楼是商场4～6楼则是办公的综合型建筑，商场共有150间各种餐厅、服饰、咖啡店等，选择多样化不必担心马上逛完或是餐厅太少。\n\n想购买当地名产或是药妆美妆品的话可以到一楼及三楼的【AEON STYLE】里找到想要的商品。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/03/14-135988.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/13-135927.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/14-135986.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/14-135984.webp"]'::jsonb, E'2023-05-29'::timestamptz, E'名古屋市'),
(E'https://matcha-jp.com/cn/7528', E'zh-Hans', 24, E'【三重 伊贺】昭和复古钱汤真霸主！文化遗产钱汤“一乃汤”', E'日本现存钱汤之中，只有5座被列为“物质文化遗产”，其中位于三重伊贺的“一乃汤”不只是作为钱汤历史最悠久，更是名符其实的“昭和复古钱汤”！刺青者无拒，也欢迎在不打扰客人的情况下拍照，想要“浸”入昭和，来这里准没错！\n\n目前全日本共有5处日本国家认定的“物质文化遗产钱汤”，各自拥有自己的特色与爱好者，今天要介绍的这间，则是喜爱钱汤的MATCHA小编心中最完美的“物质文化遗产钱汤”，更是“昭和复古风”的最佳代言人！\n\n三重县的“伊贺上野”被认为是忍者起源地之一，而全日本仅5座“物质文化遗产钱汤”中的“一乃汤”就位于此，仿佛习得忍术般静静地隐身巷弄，吸引各地的钱汤爱好者积极寻找拜访。\n\n这栋复古风味浓厚建筑诞生于1926年，当时的名字为“草津汤”，1926年是大正最后一年，也是昭和元年，这栋建筑确确实实走过整个昭和年代，也是5座物质文化遗产钱汤中，唯一建筑物从兴建至今保存完整，且作为钱汤历史上最悠久的一座。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78897.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78898.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78896.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78902.webp"]'::jsonb, E'2019-07-02'::timestamptz, E'伊贺市'),
(E'https://matcha-jp.com/cn/7166', E'zh-Hans', 24, E'【三重】似樱非樱、更胜一筹的梅花仙境！铃鹿之森庭园', E'每年2月下旬至3月下旬的铃鹿，总是吸引来自日本各地前来赏花的民众，他们的目标就是这期间限定的梅花仙境“铃鹿之森庭园”！\n\n从名古屋开车约一个多小时车程的三重县铃鹿地区，除了拥有铃鹿七大名山及驰名海外的铃鹿F1国际赛车场之外，这次小编要介绍一处鲜少外国人前往的粉色仙境“铃鹿之森庭园”，每到2月下旬至3月下旬，总是吸引来自日本各地前来赏花的民众。\n\n位于三重县北部的铃鹿之森庭园，是以八重梅的象征性品种“吴服枝垂”为中心，由赤冢植物园栽培研究的庭园，推广展现日本传统园艺的“枝垂梅嫁接技术”，平常则作为研究栽培的农园使用。\n\n园区内有约200多株的枝垂梅，吴服枝垂的垂坠方式有如烟花放射，其开花盛况一直被称为日本最大规模也最有魅力的巨树群，每年庭园会根据梅花开花时间对外开放参观，可以线上查询最新花况：https://twitter.com/Suzuka_Akatsuka', E'["https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72817.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72823.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72824.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72825.webp"]'::jsonb, E'2019-03-27'::timestamptz, E'铃鹿市'),
(E'https://matcha-jp.com/cn/4333', E'zh-Hans', 24, E'【三重县】位于忍者故乡伊贺名城：上野城', E'上野城(又名伊贺上野城)是一座位于三重县伊贺市上野的一座城池。距今为止约400年前，由统治这一地域的武将，筑城名人藤堂高虎建造。本篇文章汇总了中部名城，上野城的概要，以及访问方式等资讯。\n\n上野城(又名伊贺上野城)是一座位于三重县伊贺市上野的城池。需要注意的是，伊贺市上野与东京都的上野是两个完全不同的地方。伊贺市是忍者的故乡，位于中部地方的一个城镇 (东京属于关东地区)。\n\n上野城于距今约400年前，1608年由统治这一地域的武将、藤堂高虎建造。筑城名将藤堂高虎，除了上野城外，还建造了爱媛县的宇和岛城，今治城，兵库县的筱山城等气派的城池。\n\n上野城共有3层，是一座白色墙壁的城楼 (*1)。城楼屋顶的形状与凤凰 (*2)收起翅膀的姿势相似，所以上野城又称为白凤城。由于暴风雨的原因，高虎建立的上野城已于1612年倒塌了，现今仅保留下来了当时城中的一部分石墙，护城河等建筑。现在大家所看到的是于1935年修复过的城楼。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/05/01-25766.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/01-25767.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/01-25768.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/01-25769.webp"]'::jsonb, E'2018-05-04'::timestamptz, E'伊贺市'),
(E'https://matcha-jp.com/cn/11397', E'zh-Hans', 25, E'【滋贺】从京阪、名古屋轻松抵达！琵琶湖三都彦根、米原、长滨轻旅行', E'在古时就已是重要战略要地的滋贺县三都（彦根市、米原市、长滨市），更是留下了包含战国著名武将石田三成在内的众多知名历史景点。当然特色美食、体验活动及住宿设施更是一应俱全。无论从大阪、京都或是名古屋前往交通都快捷方便。这次就由小编带大家一同感受滋贺县湖北地区的魅力！\n\n位于琵琶湖东侧的彦根市可以说是湖东地区的中心城市，在日本地理位置上也是重要的交通枢纽之一。依稀可见的江户时期城下町的规划及繁荣景象，让彦根更具历史氛围的同时，也为城市吸引着众多游客前来。\n\n提起彦根，大家脑中首位浮现的当然是国宝彦根城。彦根城距今建城400年，是目前日本国内仅存的12个江户时代木造天守之一，更被列为国家级保护文物。现正为入选世界遗产二积极准备着。 彦根城在江户时代是德川幕府重臣井14代的居城。伊家作为替幕府镇守、监督西侧各领主的一员大将，以彦根城为据点，统治彦根一带约300年之久。\n\n彦根城天守阁内开放参观，登上天守阁最上层可以看到琵琶湖与周边地形，也因此在江户时代才会选择在此筑城，但要注意的是天守内部阶梯相当陡峭，身体不便或是有恐高症的人需要注意安全。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/10/25-131031.webp","https://resources.matcha-jp.com/resize/720x2000/2022/10/21-130979.png","https://resources.matcha-jp.com/resize/720x2000/2022/10/20-130958.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/10/21-130980.jpeg"]'::jsonb, E'2022-12-08'::timestamptz, E'彦根市'),
(E'https://matcha-jp.com/cn/9308', E'zh-Hans', 25, E'【关西】当地人首选，游客最爱！必须收藏的关西8间大型OUTLET与购物中心大解析', E'在关西地区也有众多OUTLET与购物中心方便大家购物游玩。像是离关西机场仅有一桥之隔的临空城OUTLET或神户三田OUTLET等 。 文中精选关西8间大型OUTLET和购物中心，从交通方式到推荐品牌详细介绍给大家。关西购物懒人包一定要永久收藏哦！\n\n关西地区美食美景云集自然是休闲旅游的好去处，此外像是心斋桥街或是梅田的百货公司等购物也很方便。 但其实关西还有不少大型OUTLET与购物中心，可以用非常优惠的价格入手各种好物。跟着小编一起来看看吧。\n\n关西的OUTLET和购物中心大多不在市中心，有些虽然较为偏远但是游客不多，可以悠闲购物，非常值得去走走。\n\n这边还有循环巴士可以载送您到临空城内的五间饭店，对住宿在关西机场附近的旅客来说很方便。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/01/13-133733.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/22-95575.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/24-134033.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/24-134036.webp"]'::jsonb, E'2023-02-17'::timestamptz, null),
(E'https://matcha-jp.com/cn/5507', E'zh-Hans', 25, E'【关西天气】京阪神1,2月天气与服装穿搭示范', E'春节年假想到日本关西旅行吗？大阪抢新年福袋、京都赏雪等准备行程之前先准备好穿搭行李吧！本篇提供大阪天气,京都天气的关西1,2月穿着穿搭资讯，告诉你怎么穿？关西气温有多冷？准备好保暖衣物，一起到关西度假过节吧！\n\n过年年假想到日本关西旅行吗？大阪抢福袋、京都赏雪、奈良喂鹿⋯，准备行程之前先准备好穿搭行李吧！本篇提供关西1,2月旅游穿搭资讯，告诉你怎么穿？关西气温有多冷？准备好保暖衣物，一起到关西度假过节吧！\n\n※日本关西2023年1月同期气温参考：平均温度6.5度，最高温10.3度，最低温3.1度。 ※日本关西2023年2月同期气温参考：平均温度7.0度，最高温11.0度，最低温3.7度。 ※日本关西地区包括：大阪府、京都府、兵库県、滋贺县、奈良县、和歌山县。\n\n年初的1月、2月正临冷冷的冬季，气温约为5度左右，就算太阳露脸都有可能感觉寒冷。帽子、手套、围巾等保暖御寒小物绝对不能少，若是觉得冷风刮脸不舒服，也可以携带口罩、耳罩。因为一二月正是关西地区最可能突然下雪的季节！', E'["https://resources.matcha-jp.com/resize/720x2000/2017/12/13-43761.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/13-43759.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/13-43763.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/13-43760.webp"]'::jsonb, E'2017-12-21'::timestamptz, null),
(E'https://matcha-jp.com/cn/146', E'zh-Hans', 26, E'出乎意料的便捷！从关西国际机场到京都市内的两种路线。', E'大家旅途奔波辛苦了，不过千万别担心，从机场到京都不是很远哦。今天给大家介绍一下来到关西国际机场以后如何去京都。\n\n从关西国际机场（关空）到京都市内，有很多路线可供选择。不过，大多数方式都需要经过多次换乘，也就是说，车站之间的路很复杂而且需要花费很长时间。\n\n为了避免浪费宝贵的旅行时间，向大家介绍一下到京都最好的两种路线。此次我介绍的是坐JR线。\n\n要注意一点。从关西国际机场到大阪的路线是没问题的，不过，从大阪到关西国际机场的路线要注意，从中途的车站开始车厢会被分割。前4车厢（1号到4号）是往关西国际机场走的关空快速，后4车厢（5号到8号）是往和歌山走的紀州快速。千万别坐错哦。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/02/24-123202.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/24-123203.webp"]'::jsonb, E'2014-10-29'::timestamptz, E'京都市'),
(E'https://matcha-jp.com/cn/182', E'zh-Hans', 26, E'从问路到京都原始体验之旅！令旅游者欣慰的“京都旅游咨询服务”', E'虽来到京都来很好，但是“还没决定去的地方”，“想试试只有京都有的特色”，“今天的住所还没决定”诸如此类的不安成分有许多。 不过，不用担心。有专门解决此类问题的地方。就来介绍一下，如果到京都旅游的话，对旅途有帮助的两个设施吧！\n\n不过，不用担心。有专门解决此类问题的地方。就来介绍一下，如果到京都旅游的话，对旅途有帮助的两个设施吧！\n\n首先第一个是，在京都站内的“京都综合观光咨询住”。地点是京都站2楼的西检票处右转，走30秒便可以到的地方。\n\n前台的对面排列着关于只有在京都才能体验的项目的小册子。如果没计划便来到京都的人，在这里也可以找到喜欢的项目然后挑战一下哦。听上去非常有趣呢。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/08/24-129225.webp"]'::jsonb, E'2014-11-07'::timestamptz, E'京都市'),
(E'https://matcha-jp.com/cn/967', E'zh-Hans', 26, E'夏日小确幸般的傍晚纳凉。——贵船神社七夕竹子装饰灯彩', E'日本有在7月7日夜晚向神明祈愿的七夕习俗。京都便有一处与七夕传说结缘的神社“贵船神社”。\n\n织姫和彦星因为相互过于爱慕而耽误了天神所派任的工作。天神因此大怒，将相爱的二人分离，许给2人一年只可相见一次的日子“七夕”。所以，织姫和彦星为了七夕夜愉快相会而努力工作，故事大意如此。\n\n除了这则七夕传说以外，在日本还有在农历7月7日的夜晚将写有心愿的短册（长方形小纸条）挂在竹叶上、向神明祈愿的习俗。\n\n另外，夏天来临之际，附近流淌着的贵船河的潺潺流水声也相辅相成，令人能感受到京都独有的风情。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/05/31-138737.webp","https://resources.matcha-jp.com/archive_files/jp/2015/07/DSC07280-001.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/31-138735.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/31-138736.webp"]'::jsonb, E'2019-08-18'::timestamptz, E'京都市'),
(E'https://matcha-jp.com/cn/1447', E'zh-Hans', 27, E'【交通】从东京到大阪的交通方式大比较！最划算？最快？最舒适？', E'从东京到大阪，可利用新干线、高速巴士、飞机、电车等交通方式。该怎么选呢？本文便为大家总结介绍了各个交通方式的耗时和费用，优点和注意点。比较下，选择适合自己的出行方式吧～\n\n小编猜想有不少游客两个城市都想去吧！但是东京和大阪离得可有点远，得花不少时间和费用呢！所以本篇抹茶将为您盘点东京到大阪的交通方式，为您比较费用，耗时，舒适程度，希望对您有所帮助，不花冤枉时间，也不花冤枉钱！ 使用【BicCamera】最多可省17％OFF优惠券 更多精彩介绍 【BicCamera最大17%优惠券】最新人气商品23选＆购物攻略（电器、药妆、玩具等）\n\n东海道新干线有“のぞみ”(希望号)、“ひかり”（光号）、“こだま”（回声号）、3种列车，都在新大阪站停车。其中「のぞみ」最早，约2小时半抵达新大阪站。「ひかり」约3小时，“こだま”约4小时。注意，“Japan Rail Pass”仅可用于搭乘“ひかり”“こだま”。\n\n从新大阪站坐一站可到JR大阪站，前往著名景点道顿堀附近的心斋桥站、难波站坐地下铁约15分钟便可抵达。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121628.webp","https://resources.matcha-jp.com/archive_files/jp/2015/11/JapanRailPass_20151124.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/13-128274.webp","https://resources.matcha-jp.com/archive_files/jp/2015/11/airplain_20151124.webp"]'::jsonb, E'2018-06-29'::timestamptz, E'大坂市'),
(E'https://matcha-jp.com/cn/1901', E'zh-Hans', 27, E'心斋桥商店街购物地图让你走到铁腿还是要买！', E'在大阪购物一定要去“心斋桥筋商店街”！这是一条长约600米，药妆店、美妆店、服饰店和餐厅等鳞次栉比的大型商店街。本篇详细介绍不同风格的推荐店铺和交通方式。\n\n这是离大坂观光据点难波和道顿堀较近的心斋桥。这里有大坂具有代表性的商店街「心斋桥筋商店街」。\n\n心斋桥筋商店街全长约600公尺。包含连接前后的其他商店街的话，成为一条约2公里延绵不断的商店街。聚集了药妆店、化妆品店、免税店、百圆店、动漫人物店、餐厅和咖啡店等，如果说想买的东西都可以在这里买到，一点也不过分。\n\n本篇为大家分类介绍心斋桥筋商店街都有什麽样的店铺！文章末尾也写着到达商店街的交通方式，看这一篇就不怕迷路啦！ 二手精品店「ALLU」优惠10,000日元', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61550.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61551.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61552.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/28-61432.webp"]'::jsonb, E'2018-10-23'::timestamptz, E'大坂市'),
(E'https://matcha-jp.com/cn/1931', E'zh-Hans', 27, E'【大阪】难波车站竟然有6个！？各个车站与各路线大攻略', E'难波是大坂的中心地，亦是多条电车路线的转乘站，因此在大阪一共有6个难波车站。虽然交通是十分便利，但常会让人搞不清楚自己身处的哪个难波车站，或是想去的难波车站在哪裡。 加上，不管是站名的标示、路线图还是指南大都只是用平假名写着「なんば駅」，颇为容易混淆，这也是必须注意的点。在本文中会为大家比较6个难波车站与其路线的不同\n\n代表大阪的主要转运车站之一难波(なんば)。距离道顿堀和心斎桥商店街等大阪主要观光景点很近，而且从关西国际机场(KIX)搭乘特急Rapid只要约35分，作为大阪观光的据点非常方便。\n\n不过，难波是众多电车路线的聚集点。一共6个车站，而且几乎都用同一个名字！“自己现在到底在哪个难波车站”“目的地的难波车站在哪”，很容易让人晕头转向。\n\n本文将针对6个“难波车站”的差异做比较、并介绍从各个车站容易前往的观光地点等等。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/20-60982.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/17-60815.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/17-60816.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/17-60817.webp"]'::jsonb, E'2018-10-30'::timestamptz, E'大坂市'),
(E'https://matcha-jp.com/cn/1482', E'zh-Hans', 28, E'【姫路城】抹茶带您深入细节，欣赏世界遗产&日本国宝－姬路城', E'很多游客来来日本只为走访那些城郭和城迹。这回MATCHA要来以世界知名的日本文化遗产，国宝“姫路城”为例，介绍走访“日本城”的时候，要如何欣赏一些细节的地方，这边整理了7个项目提供你参考。\n\n这回MATCHA要来以世界知名的日本文化遗产，国宝“姫路城”为例，介绍走访“日本城”的时候，要如何欣赏一些细节的地方，这边整理了7个项目提供你参考。\n\n由于石垣角边容易被破坏，以姫路城来说，可以看到其设计是使用长方形的大石块和小石块相互交替建筑，采用算木积工法。\n\n为防止敌人入侵，城的周围会挖城河(日语：堀)。姫路城周边有内丶中丶外三层城河，照片的是更内层的“三国堀”。看到水面上城墙美丽的倒影，让人几乎忘了这是为了防御所打造的。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/05/22-126970.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/22-126971.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/22-126972.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/22-126973.webp"]'::jsonb, E'2016-02-15'::timestamptz, E'姫路城'),
(E'https://matcha-jp.com/cn/2523', E'zh-Hans', 28, E'【兵库县神戸市】抹茶带我去日本三大夜景之一「摩耶山掬星台」', E'日本的三大夜景，你都看过了吗？你知道兵库县神戸市掬星台是有名的约会地点吗？这篇要告诉大家从神戸中心地带—三宫出发，往掬星台的方法。\n\n日本可以欣赏的太多，夜景也是其中之一。你知道日本有三大夜景吗？都去看过了？北海道函馆山、长崎县稲佐山，以及，兵库县神戸市的摩耶山掬星台(まやさんきくせいだい)夜景。\n\n其中，掬星台夜景更是知名的约会景点。从神戸市中心过去，交通非常方便的关系，吸引了非常多人前往。\n\n从三宫过去掬星台，基本上要搭公车、地面缆车及空中缆车。那，让我们先往公车站牌前进吧！', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120016.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120029.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120030.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120031.webp"]'::jsonb, E'2016-10-23'::timestamptz, E'神戸市'),
(E'https://matcha-jp.com/cn/3780', E'zh-Hans', 28, E'迎接开港150年，走访神戸异人馆“风见鸡之馆”旅', E'2017年迎接开港150周年的神戸市，有个外国人曾经住在这的建筑，被大家称之为“异人馆”。其中旧汤玛士邸统称“风见鸡之馆”是一个相当受欢迎的景点，每年大约有30万人走访。这是一栋被建造于1909年左右，富含异国风情的建筑物，让我们还感受一下当时的样子吧！\n\n2017年迎接开港150周年的神戸市有的外国人曾经居住的建筑物，大家称之为异人馆。其中有个被建造于1909年左右的旧汤玛士邸，统称“风见鸡之馆”，屋顶上可以看到指示风向的风向鸡，还有其咖啡砖色的外墙为此建筑物的特色。被国家指定为重要文化财，每年大约有30万人来访。\n\n首先在柜台付入场费，赶快来进去看看吧。入场费大人500日元，高中生以下免费。其他还有许多优惠，可以参考官网内的最新资讯。简介书内除了日文，也有提供英文，中文(简体字及繁体字)，以及韩文译本。\n\n一进玄关，左边有个接待室。整体的建筑，是以这间馆主，也是当时贸易商的汤玛士的母国德国传统建筑的2层木造住宅，且据说施工的人是日本的宫大工(※1)。因此窗户的外框看起来很有日本的风格。另外为配合高温多湿的日本风土气候，各方向都有设置大窗户。', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/27-12566.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/05-13254.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/24-12363.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/24-12367.webp"]'::jsonb, E'2018-01-06'::timestamptz, E'神戸市'),
(E'https://matcha-jp.com/cn/4541', E'zh-Hans', 29, E'世界遗产东大寺旁的依水园～基本资料・交通方式・可看之处介绍〜', E'依水园是位在奈良县奈良市的日式庭园，也被指定为国家名胜。庭是由江户时代所建造到小全园跟明治时代所制作的大庭园做连结。今天就要来跟大家介绍就在世界遗产东大寺附近的伊水园的基本资料、交通方式、可看之处。\n\n依水园是位在奈良县奈良市的日式庭园，这座庭园被日本政府指定为国家的文化财之一。在这里的庭，分别由江户时代所建造的「前园」以及明治时代所建造的「后园」2园连结而成。\n\n前园是在1673年由晒(※1)职人的清须美道清所建造的出来的，以「三秀亭」之称的茶室是它独特之处。比起后园，前园就稍微小了一点。\n\n后园是明治的时候由实业家的关藤次郎所建造。特征是相较于前庭坐地比较宽广。在后庭的中央有设有池塘，在里面设置人造山的筑山等的手法池泉回游式所建造出来。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/05-28016.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/05-28017.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/05-28019.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/05-28018.webp"]'::jsonb, E'2017-12-06'::timestamptz, E'奈良市'),
(E'https://matcha-jp.com/cn/5436', E'zh-Hans', 29, E'绝不只有鹿！日本奈良特色与魅力还有这些', E'奈良和京都、大坂、神户都被属于关西，但相较京坂神，奈良似乎较不被了解。对于奈良的印象，不外乎就是“大佛”、“鹿”，但其实奈良还有其他特色。既然奈良人不擅长宣传自己，那这次就由MATCHA 小编来让大家更认识奈良吧！\n\n相较于观光客熟知的京都、大坂，同样位在关西的奈良似乎较不被了解。对于奈良的印象，不外乎就是“大佛”、“鹿”，但其实奈良还有其他特色。本篇不教大家如何抵达奈良喂鹿，而是要告诉你奈良和京都、大坂等其他县市有何不同，既然奈良人不擅长宣传自己，那这次就由MATCHA 小编来让大家更认识奈良吧！\n\n日本历史上名叫“飞鸟”的地方就是在现今的奈良“明日香村”，其为日本最古老的京城。因为京城不断迁移，后来才定在京都。换句话说，在京都变为首都之前，首都一直在奈良。\n\n相较于京都的优雅尊贵的和风情怀，对于奈良的印象大多被认为较朴实、甚至古得有些土气。但曾有位日本艺人说过“过了三十岁后，慢慢能发现奈良的魅力。”相较于充满观光客的拥挤巷弄，走在奈良显得悠闲许多，能细细品味拥有千年以上历史的建筑、古迹，若想亲自见证“最原始的日本”，那么你一定要来奈良看看。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42592.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42588.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42587.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42589.webp"]'::jsonb, E'2017-12-05'::timestamptz, E'明日香村'),
(E'https://matcha-jp.com/cn/11023', E'zh-Hans', 29, E'探访世界遗产法隆寺与日本史的小镇【斑鸠町】', E'提到奈良，或许大家都是醉心于可爱的小鹿，但你知道有着深厚历史文化的奈良有更多可看之处吗？奈良西北部有一个叫【斑鸠町】的地方，有着与圣德太子有着深厚渊源且是世界遗产的法隆寺及法起寺，还有据说是斑鸠起源的“龙田炸鸡”这美食，要不要跟着小编去走一趟不一样的奈良呢？\n\n离JR法隆寺站徒步约20分钟的吉田寺开基于西元987年，据说在丈六阿弥陀如来像（像高5.15公尺）前祈祷，可以“没有病痛，安祥地的离开人世”一说。\n\n御朱印帐是前往神社或寺庙的参拜证明册；时至今日变成旅游的纪念方式之一，在访日外国人旅客中也相当有人气。吉田寺内有提供制作专属朱印帐的体验项目（需事前预约），如果想要与众不同的御朱印帐，这手作体验是不错的选择。\n\n首先要挑选自己喜欢的封面和封底，除了有季节限定的和纸外，亦有来自尼泊尔等地特殊的印刷设计可供选择。由于种类繁多，让体验者大多在挑选花样时犹豫不已，花上较多时间。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/22-121260.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/23-121262.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/23-121261.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/23-121263.webp"]'::jsonb, E'2022-02-15'::timestamptz, E'斑鸠町'),
(E'https://matcha-jp.com/cn/4879', E'zh-Hans', 30, E'【和歌山】世界遗产熊野三山，灵魂终点生命起点“熊野本宫大社”', E'和歌山的熊野三山，又称为熊野三社，皆在熊野古道名列世界遗产，被誉为“神灵居住之地”，这里的一切与自然息息相关，是日本人的心灵圣地。其中坐落和歌山县山林之中的熊野本宫大社，大斋原被称为灵魂的终点、生命的起点，同时也是拥有日本最大的鸟居。\n\n熊野三山，又称为熊野三社，包括熊野速玉大社、熊野本宫大社与熊野那智大社。至三社所经的熊野古道与神社名列世界遗产，被誉为“神灵居住之地”，这里的一切与自然息息相关，是日本人的心灵圣地。\n\n位于和歌山的熊野古道，距今已有超过千年历史。传说在一一六四年，神明降临熊野地区，这里遂成为“神灵居住之地”，信徒远从全国各地而来，人数之多，让古道上满是人潮，被称为蚂蚁的熊野参拜（蚁の熊野诣）。2004年，以“纪伊山地的圣地与参拜道”，简称熊野古道，登录世界遗产，也是世界唯二登录世界遗产的古道。\n\n熊野本宫大社，位于和歌山县田边市本宫町，处于山林之中，可以由JR新宫站、JR那智站或JR胜浦站乘坐巴士前往，单趟1540元，若是想体验古人参拜临场感，可以乘坐巴士至古道中边路区，再攀爬石阶前往本宫大社。古道路线请参考这边', E'["https://resources.matcha-jp.com/resize/720x2000/2017/08/02-32723.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/13-33432.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/13-33433.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/13-33434.webp"]'::jsonb, E'2017-11-25'::timestamptz, E'熊野三山'),
(E'https://matcha-jp.com/cn/4963', E'zh-Hans', 30, E'【和歌山】世界遗产熊野三山，“熊野那智大社”与“那智瀑布”', E'和歌山的熊野三山，又称为熊野三社，皆在熊野古道名列世界遗产，被誉为“神灵居住之地”，这里的一切与自然息息相关，是日本人的心灵圣地。其中被视为熊野信仰起源的熊野那智大社，与邻近的那智瀑布，经典的三重塔与飞瀑，是熊野古道朝圣不可错过的景色。\n\n位于和歌山的熊野古道，距今已有超过千年历史。传说在一一六四年，神明降临熊野地区，这里遂成为“神灵居住之地”，信徒远从全国各地而来，人数之多，让古道上满是人潮，被称为蚂蚁的熊野参拜（蚁の熊野诣）。2004年，以“纪伊山地的圣地与参拜道”，简称熊野古道，登录世界遗产，也是世界唯二登录世界遗产的古道。\n\n熊野那智大社，位于和歌山县那智胜浦町。那智胜浦是一个小小的渔村，每年夏季朝圣古道的游客到来，总会为这里带来许多生气，观光淡季时，这里就是宁静平和，居民悠闲度日。\n\n从JR纪伊胜浦站前，有巴士直接前往熊野那智大社，班次一个小时一班。巴士是往“那智山”，途中会经过熊野古道大门坂，若想体验古道风光，要记得在“大门坂驻车场前”下车喔。公车时刻表看这边', E'["https://resources.matcha-jp.com/resize/720x2000/2017/08/02-32723.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/29-34647.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/29-34648.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/29-34649.webp"]'::jsonb, E'2017-11-27'::timestamptz, E'熊野三山'),
(E'https://matcha-jp.com/cn/25844', E'zh-Hans', 30, E'高野山私人一日游｜世界遗产高野山行程范例', E'从大阪出发，乘坐火车和缆车，一日游世界遗产高野山。 上午，我们将参观高野山的大门——高野山的入口；真言宗的中心——坛上伽蓝；以及总本山——金刚峰寺。下午，我们将参观德川家的陵墓，最后前往高野山最吸引人的景点——奥之院。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/17-244585.webp"]'::jsonb, E'2025-09-27'::timestamptz, E'高野山'),
(E'https://matcha-jp.com/cn/3725', E'zh-Hans', 31, E'【山阴】鸟取好好玩 ！内行人必去五大超推景点', E'鸟取，一个常跟岛根傻傻分不清楚的地方。在2016年“全国47都道府县魅力排行”中，更获得倒数第五名，鸟取真的如此的没魅力吗？不不不~鬼太郎作者故乡,柯南博物馆,鸟取沙丘,白兔神社等等地点可多着呢！快跟Matcha小编一起看下去吧！\n\n提到鸟取，别说旅客常搞混，就连日本人也常常将鸟取与隔壁的岛根搞错。在2016年“全国47都道府县魅力排行”中，鸟取县获得倒数第五名，远远落后隔壁岛根县。鸟取县真的有这么无聊吗？其实鸟取有很多景点，内行人都知道，但是内行人都不说，今天就一起揭开鸟取县充满魅力的景点吧！\n\n日本公认的妖怪博士，经典妖怪漫画“鬼太郎”的作者水木茂老师，出身正是鸟取县，大师故乡的境港，也顺理成章地成为鬼太郎的故乡。鸟取县相当敬重水木茂老师，也把鬼太郎当作地方骄傲，从把鸟取县米子机场取名为“米子鬼太郎机场”就可略知一二，当然地上跑的电车也没放过，一样设计成鬼太郎列车。\n\n境港处处可见鬼太郎作品里的人物雕像，连路灯、计程车等，也都是与鬼太郎相关的设计。其中这个位于车站前的雕像，刻画的是鬼太郎与鼠男，望着创作自己的水木茂大师的场景，让人备感温馨，而水木茂老师本人也已于2016年底逝世，但粉丝们都觉得老师一定是开心地与鬼太郎们跑去找妖怪玩了。', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11549.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11550.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11551.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/12-11443.webp"]'::jsonb, E'2018-02-06'::timestamptz, E'鸟取市'),
(E'https://matcha-jp.com/cn/6225', E'zh-Hans', 31, E'在鸟取的灵峰・大山体验日本的神圣祭典！神秘的“火把节”', E'每年6月，鸟取县的大山将举办“大山夏季开山祭”。其一系列行事之中，“火把节”是一项非常庄严且神秘的行事。本文将为大家介绍“火把节”的体验报告，参加方式和注意点等。\n\n日本文化吸引着八方游客的理由之一，便是总是带给我们各种新鲜和精彩，冲击着我们的价值观。源远流长的日本文化，深深根植于国民的精神世界之中，吸引着我们一次次前往日本，想要接触人民的日常，他们的心灵。\n\n如本文将介绍的一样，鸟取的大山夏山开き祭 (前夜祭)（大山夏季开山祭）中举办的“たいまつ行列”（火把节），可谓是给人印象深刻，甚至能影响人生观的日本文化之一呢。\n\n这个日本行事，于毎年6月举办，从夕阳西下一直到夜晚，约有2000个参加者，手拿火把，沿着参拜道路一路往下走。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/21-56897.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/21-56898.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/20-56819.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/20-56820.webp"]'::jsonb, E'2018-08-16'::timestamptz, E'大山'),
(E'https://matcha-jp.com/cn/4724', E'zh-Hans', 31, E'明明超好玩！“日本最不有名的县”鸟取县V.S.岛根县好吃好玩报你知！', E'如果问日本人日本的哪个县最不有名，八九不离十绝对就是“鸟取县”或“岛根县”。但其实除了交通上比较不方便之外，鸟取县和岛根县有非常多值得一看的独家景色如鬼太郎神社,鸟取沙丘,柯南博物馆,出云大社及美食！MATCHA小编今天一定要帮这两个县好好平反一下，介绍给大家！\n\n如果问日本人日本的哪个县最不有名，得到的回答不是“鸟取县”就是“岛根县”。岛根县不仅被戏笑是日本第47名有名的县（也就是最后一名笑），地方团体也出了一本书“岛根县自虐传”，透过这种独特的“反行销”只为了让更多人能认识这个地方。但其实除了交通上比较不方便之外，鸟取县和岛根县有非常多值得一看的独家景色及美食！MATCHA小编今天一定要帮这两个县好好平反一下，介绍给大家！\n\n首先，鸟取县及岛根县位在日本本州“西部”的山阴地区，北临日本海。而鸟取县及岛根县由于地图形状长的很像，都是横的细长条形，加上知名度不高，因此很常被搞混。相对位置上，鸟取县位于岛根县的右边。\n\n不管喜不喜欢鬼太郎，到这都会为之疯狂的鬼太郎村！之所以境港站也能称作“鬼太郎站”，是因为整个车站及附近都围绕着鬼太郎的主题，走到哪都能见到鬼太郎的身影。鬼太郎的作者是有“妖怪博士”之称的日本漫画家水木茂先生，从1959年开始连载，加上不断推出最新动画，可以说是现在日本人小时候的共通回忆！这里有鬼太郎风格的神社、商店街还有纪念馆等等。 更多详细请看：超强结缘、鬼太郎、砂丘一次集满！用“山阴满吃PASS两日券”玩遍鸟取＆岛根', E'["https://resources.matcha-jp.com/resize/720x2000/2017/07/12-30897.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/12-30907.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/12-30910.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/12-30916.webp"]'::jsonb, E'2018-05-27'::timestamptz, E'鸟取市'),
(E'https://matcha-jp.com/cn/7642', E'zh-Hans', 32, E'【岛根】不只有出云大社！岛根自由行十大必去景点・交通方式・美食攻略', E'岛根县有出云大社和松江的城下町等许多歴史悠久名胜景致。还有玉造和温泉津等温泉胜地，宍道湖和隠岐诸岛的景色也充满魅力。本文将介绍岛根县的必去景点、从东京和大坂出发的交通方式、当地美食等攻略。\n\n出云大社自古以来就是人们信奉的日本全国众神集结的神社，现在则是有名的良缘(※1)景点。岛根的中心松江是保留古色古香风景的城下町。除了可以欣赏许多日本绘画和日本庭园的足立美术馆，还有蚬的渔获量日本第一的宍道湖。\n\n松江附近的玉造和温泉津等温泉街也可以放松。县内可以品尝鲈鱼等海鲜，还有出云荞麦面、岛根和牛和日本酒等丰富美食。\n\n搭船前往的隠岐诸岛岛后有日本海的浪花拍打下形成的断崖峭壁和美丽的夕阳等风景。 用有日本歴史建筑、文化和大自然的岛根。以下介绍几个必去的景点。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81186.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/04-85224.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81187.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81188.webp"]'::jsonb, E'2019-10-26'::timestamptz, E'出云大社'),
(E'https://matcha-jp.com/cn/8269', E'zh-Hans', 32, E'缘起缘生神之乡——欢迎来到【星野集团 界 玉造】', E'位于岛根县的【星野集团 界 玉造】是知名的玉造温泉的休闲度假旅馆。岛根被誉为日本神话之乡，众神集聚，为每一位来访的游客带去一段最美的相遇。\n\n出云是现在的岛根县的旧称，在日本的古典名著《古事记》中，被记载为日本神话的舞台。据传，11月间，日本众神都将聚集于出云大社里。\n\n而来访于此地的游客，无论是工作还是个人都会有好事发生，也因此被称为是【结缘圣地】。\n\n日本最古老的温泉之一，玉造温泉的【星野集团 界 玉造】，正在神之乡静候有缘人的光临。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/12/05-92395.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92578.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92581.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92582.webp"]'::jsonb, E'2019-12-26'::timestamptz, E'出云大社'),
(E'https://matcha-jp.com/cn/3804', E'zh-Hans', 32, E'【岛根县】14年连续蝉联第一的日本庭园！“足立美术馆”', E'“足立美术馆”位于岛根县安来市，以日本画为中心展示各种艺术作品。美术馆的面积有5万坪之大，打造了许多山水美景，是日本国内最大的庭园。\n\n美国的日本庭园杂志《SUKIYA LIVING MAGAZINE》中，这个庭园在排行榜已经蝉联17年第一，豪无疑问是日本最具代表性的庭园了。\n\n足立美术馆分成两个部分。本馆是展示近代日本画、陶艺以及庭园。新馆则是展示现代日本画和企划活动专区。如果想看庭园，就来去本馆吧。\n\n足立美术馆的构想是将“日本庭园和日本画中的意境融合起来”。本馆1楼可以观赏庭园景观。到了2楼会看到日本画名匠横山大观等等大师级的作品，这也是创立者足立全康心爱的收藏。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15155.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15151.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15161.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15162.webp"]'::jsonb, E'2018-01-22'::timestamptz, E'安来市'),
(E'https://matcha-jp.com/cn/21467', E'zh-Hans', 33, E'「冈山」的天气特征！四季最佳服装和推荐观光景点介绍！', E'冈山县因天气良好而被称为“晴天的国度”，但四季分明，因此根据不同的气候需要选择相应的服装。倉敷美观地区和后乐园等，冈山拥有众多观光景点，为了最大程度地享受这些魅力，服装的选择非常重要。在这里，我们将介绍冈山的季节别气温、最佳服装和推荐的观光景点等信息。\n\n由于冈山县四季分明，因此服装必须根据每个季节的气温来选择。冈山以晴天多而闻名，但在6月到7月的梅雨期间，降雨也相对频繁，因此选择能应对恶劣天气的服装也非常重要。接下来将解释冈山的天气特征、四季的天气趋势以及最佳服装推荐，还会介绍一些推荐的樱花景点和观光景点。\n\n年降水量低于全国平均，日照时间长，因此被称为“晴天的国度”。降水量在6月到7月的梅雨季节较多，并且不容易受到台风和降雪等自然灾害的影响。\n\n春季和秋季气候宜人，夏季有些天气温度会超过30度，但北方的凉风和瀬户内海的和风使得早晚仍感到凉爽。冬季偶尔会有寒冷的日子，但雪下得很少，因此整体而言比较温和。在恶劣天气下交通混乱的情况也不会频繁发生，让人感到安心。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195646.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195641.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195642.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195643.webp"]'::jsonb, E'2024-09-05'::timestamptz, E'冈山市'),
(E'https://matcha-jp.com/cn/11842', E'zh-Hans', 33, E'西日本最大规模购物中心，【AEON永旺梦乐城冈山】', E'JR冈山站前的【AEON永旺梦乐城冈山】是AEON MALL西日本最大规模的购物中心，在2022年改装重新开幕，更多店家提供免税服务，并扩大当地特色伴手礼区域以迎合多样化的消费者需求，从服饰杂货、到当地美食、伴手礼，换然一新的【AEON永旺梦乐城冈山】魅力升级，好物多多！\n\n冈山车站从后乐园口，就可以看到通往AEON MALL标示的地下道，，从地下道走过去十分轻松！如果是有拉行李的朋友，从车站走出来右转就可以看到AEON Mall的招牌，也完全不会迷路。\n\n原本就是中国地区最大规模的商城，拥有约有300家店家，改装后在2022年又重新开幕，像是第一次进出冈山Hobby Zone、扭蛋机台俱全的TOYS SPOT PALO等，约有100家店铺开幕即整修再开幕，尤其约有40家店提供免税服务，简直就是冈山购物圣地。\n\nSENSE OF PLACE by URBAN RESEARCH是URBAN RESEARCH旗下适合年轻人的品牌之一，从男女服饰、包包鞋子，甚至是配件小物，都能搭上当下的时尚潮流，友善的价格再加上免税服务，在这里可以尽情地添购从头到脚的全身服饰。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/05/23-138451.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136380.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136381.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136383.webp"]'::jsonb, E'2023-06-08'::timestamptz, E'冈山市'),
(E'https://matcha-jp.com/cn/9398', E'zh-Hans', 33, E'5天之内乘坐不限次！不到1万5千日元的【关西&广岛地区铁路周游券】带你游遍冈山・广岛', E'因漂浮在海面的严岛神社大鸟居而为人所熟知的宫岛，尾道和仓敷风情万种的小镇，拥有诸多魅力景点的广岛县和冈山县一带，使用价格不到1万5千日元的【关西广岛区域通票】就能在五天中便捷通畅地在这一地区之间往来，本文将为大家推荐介绍以此为前提的旅游路线。\n\n紧邻濑户内海的广岛县和冈山县，有许多吸引人的好去处。像是大受欢迎的历史古镇尾道和仓敷，因美丽的严岛神社而为人们所熟知的宫岛都在这一区域。\n\nJR西日本的铁路周游券【关西&广岛地区铁路周游券】能够让你在这一区域便利地往返。\n\nJR铁路的周游券，比较有名的是7天之内随意乘坐JR铁路的【Japan Rail Pass】，价格不到3万日元。而【关西&广岛地区铁路周游券】则是主要用于关西地区的一个更加实惠的选择。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/02/07-96674.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/18-99694.webp","https://resources.matcha-jp.com/resize/720x2000/2020/02/13-97033.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/06-98923.webp"]'::jsonb, E'2020-03-17'::timestamptz, E'冈山市'),
(E'https://matcha-jp.com/cn/4435', E'zh-Hans', 34, E'【广岛县】前往世界遗产之原爆圆顶，和平纪念公园的交通和其看点', E'本篇文章将会介绍广岛和平纪念馆的交通和可见之处。文章内会介绍园内的联合国世界遗产「原爆圆顶」、展示原子弹被投下时的广岛资料「广岛和平纪念资料馆」以及追悼被爆者设施「国立广岛原爆者死亡追悼和平馆」。\n\n广岛和平纪念公园是位在广岛县广岛市中区的市民公园。是建造在1945年8月6日美军投下原子弹爆发中心处附近的公园。\n\n在园内设有3个设施，分别是联合国世界遗产的“原爆圆顶”、展示有广岛被投下原子弹当时相关资料的“广岛和平纪念资料馆”、追悼被爆者的“国立广岛原爆死者追悼平和纪念馆”。\n\n除此之外，还有纪念因原爆而死亡的“原爆死者慰灵碑”、以佐佐木祯子(ささきさだこ)为首因被爆原子弹引发白血病而早死的孩子们的“原爆之子之像”以及被爆后也一直已枯萎状态活到现在的“青桐的树”。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/05/16-26513.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/16-26512.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/16-26511.webp"]'::jsonb, E'2017-06-06'::timestamptz, null)
